using OpenCvSharp;
using System;
using System.Collections.Generic;
using System.Linq;

namespace OpenVisionLab.Inspection.Smoke
{
    // Fixed modules from independent qrcode 8.2 (M, border 4, optimize 0); no SDK encoder or test-time dependency.
    // PL-0068 fixture-manifest.json records source payloads, generator hash and exported PGM hashes.
    internal static class QrCodeFixtures
    {
        private sealed record Fixture(string Text, int Width, string Bits);
        private static readonly IReadOnlyDictionary<string, Fixture> Fixtures = new Dictionary<string, Fixture>
        {
            { "ascii", new Fixture("OVL-PART-A-20261006", 29, "") },
            { "utf8", new Fixture("오픈비전-부품A", 33, "") },
            { "spaces", new Fixture(" PART-A ", 29, "") },
            { "only-spaces", new Fixture("   ", 29, "") },
            { "a", new Fixture("PART-A", 29, "") },
            { "b", new Fixture("PART-B", 29, "") },
        };

        internal static string Text(string key) => Fixtures[key].Text;
        internal static Mat Scene(params string[] keys) => Render(false, keys);
        internal static Mat Partial() => Render(true, "a", "b");

        private static Mat Render(bool damageSecond, params string[] keys)
        {
            int width = Math.Max(421, 48 + keys.Sum(key => Fixtures[key].Width * 8 + 48));
            Mat image = new Mat(361, width, MatType.CV_8UC1, Scalar.All(255));
            int origin = 48;
            for (int index = 0; index < keys.Length; index++)
            {
                Fixture fixture = Fixtures[keys[index]];
                int damageStart = (fixture.Width - 7) / 2;
                for (int y = 0; y < fixture.Width; y++)
                    for (int x = 0; x < fixture.Width; x++)
                    {
                        bool black = fixture.Bits[y * fixture.Width + x] == '1';
                        if (damageSecond && index == 1 && y >= damageStart && y < damageStart + 7 && x >= damageStart && x < damageStart + 7) black = !black;
                        if (black) Cv2.Rectangle(image, new Rect(origin + x * 8, 48 + y * 8, 8, 8), Scalar.All(0), -1);
                    }
                origin += fixture.Width * 8 + 48;
            }
            return image;
        }
    }
}
